    res("other-stack", "volume", null, [], "stk-feat-ab"),
    res("other-branch", "volume", "feat-ab"),
  ];
  assert.deepEqual(buildPlan(resources, "feat-a").steps.map((s) => s.id), ["tagged", "stack-only"]);
});

test("deletion order handles shuffled graphs, shared dependencies and missing prerequisites", () => {
  const resources = [
    res("volume", "volume", "feat-a"),
    res("snapshot", "snapshot", "feat-a", ["volume"]),
    res("network", "network", "feat-a"),
    res("instance", "instance", "feat-a", ["subnet", "volume", "external"]),
    res("subnet", "subnet", "feat-a", ["network"]),
    res("dns", "dns_record", "feat-a", ["lb"]),
    res("lb", "load_balancer", "feat-a", ["subnet"]),
  ];
  for (const input of [resources, [...resources].reverse()]) {
    const before = structuredClone(input);
    const ids = buildPlan(input, "feat-a").steps.map((s) => s.id);
    assert.equal(new Set(ids).size, resources.length);
    for (const r of resources) {
      for (const dep of r.depends_on.filter((id) => ids.includes(id))) {
        assert.ok(ids.indexOf(r.id) < ids.indexOf(dep), `${r.id} must precede ${dep}`);
      }
    }
    assert.deepEqual(input, before);
  }
  assert.deepEqual(buildPlan([], "feat-a").steps, []);
});

test("external dependents block stack-owned resources without being selected", () => {
  const resources = [
    res("volume", "volume", null, [], "stk-feat-a"),
    res("instance", "instance", "feat-b", ["volume"], "stk-feat-b"),
  ];
  const plan = buildPlan(resources, "feat-a");
  assert.deepEqual(plan.steps.map((s) => s.id), ["volume"]);
  assert.deepEqual(plan.blocked, [{ id: "volume", dependents: ["instance"] }]);
});

test("cycles fail planning instead of returning an unsafe deletion order", () => {
